const MARK_SECTIONS = {"1":[{"title":"Jan Křtitel připravuje cestu","range":"Mk 1,1–8","thoughts":[],"verses":[[1,"Počátek evangelia Ježíše Krista, Božího Syna."],[2,"Jak je napsáno v prorocích: „Hle, posílám před tebou svého posla, který připraví tvou cestu.“"],[3,"„Hlas volajícího na poušti: Připravte Pánovu cestu, narovnejte jeho stezky.“"],[4,"Jan křtil na poušti a hlásal křest pokání na odpuštění hříchů."],[5,"Přicházela k němu celá judská krajina i lidé z Jeruzaléma. Vyznávali své hříchy a nechávali se od něho křtít v Jordánu."],[6,"Jan nosil oděv z velbloudí srsti, kolem pasu kožený pás a jedl kobylky a lesní med."],[7,"Kázal: „Za mnou přichází někdo silnější než já. Nejsem hoden ani se sklonit a rozvázat mu řemínek u sandálů.“"],[8,"„Já jsem vás křtil vodou, ale on vás bude křtít Duchem svatým.“"]]},{"title":"Ježíšův křest a pokušení","range":"Mk 1,9–13","thoughts":[],"verses":[[9,"V těch dnech přišel Ježíš z galilejského Nazareta a Jan ho pokřtil v Jordánu."],[10,"Hned když vystupoval z vody, uviděl otevřená nebesa a Ducha, jak na něj sestupuje jako holubice."],[11,"A z nebe zazněl hlas: „Ty jsi můj milovaný Syn, v tobě mám zalíbení.“"],[12,"Hned potom ho Duch vedl na poušť."],[13,"Byl na poušti čtyřicet dní a satan ho pokoušel. Byl mezi divokými zvířaty a andělé mu sloužili."]]},{"title":"Začátek Ježíšova působení","range":"Mk 1,14–15","thoughts":[],"verses":[[14,"Když byl Jan uvězněn, přišel Ježíš do Galileje a hlásal evangelium Božího království."],[15,"Říkal: „Čas se naplnil a Boží království se přiblížilo. Čiňte pokání a věřte evangeliu.“"]]},{"title":"Povolání prvních učedníků","range":"Mk 1,16–20","thoughts":[],"verses":[[16,"Když šel podél Galilejského jezera, uviděl Šimona a jeho bratra Ondřeje, jak vrhají síť do jezera, protože byli rybáři."],[17,"Ježíš jim řekl: „Pojďte za mnou a udělám z vás rybáře lidí.“"],[18,"Oni hned nechali sítě a šli za ním."],[19,"Když poodešel o něco dál, uviděl Jakuba, syna Zebedeova, a jeho bratra Jana, jak na lodi spravují sítě."],[20,"Hned je zavolal. Oni nechali svého otce Zebedea na lodi s najatými pracovníky a šli za ním."]]},{"title":"Ježíš učí v Kafarnaum","range":"Mk 1,21–28","thoughts":[],"verses":[[21,"Přišli do Kafarnaum. Hned v sobotu Ježíš vešel do synagogy a učil."],[22,"Lidé žasli nad jeho učením, protože je učil jako ten, kdo má autoritu, a ne jako učitelé Zákona."],[23,"V jejich synagoze byl člověk s nečistým duchem. Ten vykřikl:"],[24,"„Co je ti po nás, Ježíši Nazaretský? Přišel jsi nás zahubit? Vím, kdo jsi: Boží Svatý.“"],[25,"Ježíš mu pohrozil: „Mlč a vyjdi z něho!“"],[26,"Nečistý duch člověkem zalomcoval, hlasitě vykřikl a vyšel z něho."],[27,"Všichni užasli a ptali se jeden druhého: „Co to je? Jaké nové učení! S mocí přikazuje i nečistým duchům a oni ho poslouchají.“"],[28,"Zpráva o něm se rychle rozšířila po celém okolí Galileje."]]},{"title":"Uzdravení Petrovy tchyně a dalších nemocných","range":"Mk 1,29–34","thoughts":[],"verses":[[29,"Jakmile vyšli ze synagogy, šli s Jakubem a Janem do domu Šimona a Ondřeje."],[30,"Šimonova tchyně ležela v horečce a hned mu o ní řekli."],[31,"Ježíš k ní přistoupil, vzal ji za ruku a pozvedl ji. Horečka ji opustila a ona jim začala sloužit."],[32,"Večer po západu slunce k němu přiváděli všechny nemocné a posedlé."],[33,"Celé město se shromáždilo přede dveřmi."],[34,"Uzdravil mnoho lidí trpících různými nemocemi a vyhnal mnoho démonů. Démonům nedovoloval mluvit, protože věděli, kdo je."]]},{"title":"Ježíš káže po Galileji","range":"Mk 1,35–39","thoughts":[],"verses":[[35,"Časně ráno, ještě za tmy, Ježíš vstal, vyšel ven a odešel na opuštěné místo, kde se modlil."],[36,"Šimon a ti, kdo byli s ním, ho začali hledat."],[37,"Když ho našli, řekli mu: „Všichni tě hledají.“"],[38,"Ježíš jim odpověděl: „Pojďme jinam, do okolních městeček, abych kázal i tam. Proto jsem přišel.“"],[39,"A kázal v jejich synagogách po celé Galileji a vyháněl démony."]]},{"title":"Očištění malomocného","range":"Mk 1,40–45","thoughts":[],"verses":[[40,"Přišel k němu malomocný, prosil ho, klekl před ním a řekl: „Chceš-li, můžeš mě očistit.“"],[41,"Ježíš se nad ním slitoval, vztáhl ruku, dotkl se ho a řekl: „Chci. Buď čistý.“"],[42,"Jakmile to řekl, malomocenství od něho odešlo a byl očištěn."],[43,"Ježíš ho přísně napomenul a hned ho poslal pryč."],[44,"Řekl mu: „Dávej pozor, nikomu nic neříkej. Jdi, ukaž se knězi a za své očištění přines oběť, kterou přikázal Mojžíš, na svědectví pro ně.“"],[45,"On však odešel a začal o tom všude mnoho mluvit a zprávu šířit. Ježíš už proto nemohl veřejně vstoupit do města a zůstával venku na opuštěných místech. Lidé k němu přicházeli ze všech stran."]]}]};

MARK_SECTIONS["2"] = [{"title":"Uzdravení ochrnutého","range":"Mk 2,1–12","thoughts":[],"verses":[[1,"Po několika dnech Ježíš znovu přišel do Kafarnaum a rozneslo se, že je doma."],[2,"Shromáždilo se tolik lidí, že se nevešli ani přede dveře. Ježíš jim hlásal slovo."],[3,"Přišli k němu čtyři muži a nesli ochrnutého."],[4,"Protože se kvůli zástupu nemohli k Ježíšovi dostat, odkryli nad místem, kde byl, střechu. Udělali otvor a spustili dolů lůžko, na kterém ochrnutý ležel."],[5,"Když Ježíš viděl jejich víru, řekl ochrnutému: „Synu, tvé hříchy jsou ti odpuštěny.“"],[6,"Seděli tam někteří učitelé Zákona a ve svých srdcích uvažovali:"],[7,"„Jak může takhle mluvit? Rouhá se. Kdo může odpouštět hříchy kromě samotného Boha?“"],[8,"Ježíš ve svém duchu hned poznal, že takto uvažují, a řekl jim: „Proč o tom ve svých srdcích přemýšlíte?“"],[9,"„Co je snazší říct ochrnutému: Tvé hříchy jsou ti odpuštěny, nebo: Vstaň, vezmi své lůžko a choď?“"],[10,"„Abyste však věděli, že Syn člověka má na zemi moc odpouštět hříchy“ — řekl ochrnutému —"],[11,"„tobě říkám: Vstaň, vezmi své lůžko a jdi domů.“"],[12,"On hned vstal, vzal lůžko a přede všemi odešel. Všichni žasli, oslavovali Boha a říkali: „Něco takového jsme ještě nikdy neviděli.“"]]},{"title":"Povolání Léviho","range":"Mk 2,13–17","thoughts":[],"verses":[[13,"Ježíš znovu vyšel k jezeru. Přicházel k němu celý zástup a on je učil."],[14,"Když šel dál, uviděl Léviho, syna Alfeova, sedět v celnici a řekl mu: „Následuj mě.“ On vstal a následoval ho."],[15,"Když potom Ježíš stoloval v jeho domě, sedělo s ním a s jeho učedníky také mnoho celníků a hříšníků, protože jich bylo mnoho a následovali ho."],[16,"Když učitelé Zákona a farizeové viděli, že jí s celníky a hříšníky, ptali se jeho učedníků: „Proč jí a pije s celníky a hříšníky?“"],[17,"Ježíš to uslyšel a řekl jim: „Lékaře nepotřebují zdraví, ale nemocní. Nepřišel jsem volat spravedlivé, ale hříšníky k pokání.“"]]},{"title":"Otázka půstu","range":"Mk 2,18–22","thoughts":[],"verses":[[18,"Janovi učedníci a farizeové se postili. Přišli tedy k Ježíšovi a zeptali se: „Proč se Janovi učedníci a učedníci farizeů postí, ale tvoji učedníci se nepostí?“"],[19,"Ježíš jim řekl: „Mohou se svatební hosté postit, dokud je ženich s nimi? Dokud mají ženicha mezi sebou, nemohou se postit.“"],[20,"„Přijdou však dny, kdy jim bude ženich vzat. Tehdy se budou postit.“"],[21,"„Nikdo nepřišívá záplatu z nové látky na starý oděv. Jinak nová záplata odtrhne kus staré látky a trhlina se ještě zvětší.“"],[22,"„A nikdo nelije nové víno do starých měchů. Jinak nové víno měchy roztrhne, víno vyteče a měchy se zničí. Nové víno se musí lít do nových měchů.“"]]},{"title":"Ježíš je Pánem soboty","range":"Mk 2,23–28","thoughts":[],"verses":[[23,"Jednou Ježíš procházel v sobotu obilím. Jeho učedníci cestou začali trhat klasy."],[24,"Farizeové mu řekli: „Podívej, proč dělají v sobotu něco, co není dovoleno?“"],[25,"Ježíš jim odpověděl: „Nikdy jste nečetli, co udělal David, když byl v nouzi a měl hlad on i ti, kdo byli s ním?“"],[26,"„Jak za velekněze Abiatara vešel do Božího domu, jedl posvátné chleby, které směli jíst jen kněží, a dal i těm, kdo byli s ním?“"],[27,"Potom jim řekl: „Sobota byla učiněna pro člověka, ne člověk pro sobotu.“"],[28,"„Proto je Syn člověka Pánem i nad sobotou.“"]]}];

MARK_SECTIONS["3"] = [{"title":"Uzdravení člověka s ochrnutou rukou","range":"Mk 3,1–6","thoughts":[],"verses":[[1,"Ježíš znovu vešel do synagogy. Byl tam člověk s ochrnutou rukou."],[2,"Pozorovali Ježíše, zda ho v sobotu uzdraví, aby ho mohli obžalovat."],[3,"Řekl člověku s ochrnutou rukou: „Postav se doprostřed.“"],[4,"Potom se jich zeptal: „Je dovoleno v sobotu dělat dobře, nebo zle? Zachránit život, nebo zabít?“ Oni však mlčeli."],[5,"Ježíš se na ně rozhlédl s hněvem a zarmoutil se nad tvrdostí jejich srdce. Řekl tomu člověku: „Natáhni ruku.“ On ji natáhl a jeho ruka byla uzdravena."],[6,"Farizeové vyšli ven a hned se s Herodiány radili, jak by Ježíše zahubili."]]},{"title":"Zástupy u jezera","range":"Mk 3,7–12","thoughts":[],"verses":[[7,"Ježíš odešel se svými učedníky k jezeru a šel za ním veliký zástup z Galileje i z Judska,"],[8,"z Jeruzaléma, Idumey, Zajordání a z okolí Týru a Sidónu. Když lidé slyšeli, jak veliké věci dělá, přicházeli k němu ve velkém množství."],[9,"Ježíš řekl svým učedníkům, aby pro něj kvůli zástupu měli připravenou malou loď, aby ho lidé netlačili."],[10,"Mnohé totiž uzdravil, takže se na něj tlačili všichni, kdo trpěli nějakou nemocí, aby se ho mohli dotknout."],[11,"Kdykoli ho nečistí duchové uviděli, padali před ním a křičeli: „Ty jsi Boží Syn!“"],[12,"On jim však přísně přikazoval, aby ho neprozrazovali."]]},{"title":"Ježíš ustanovuje Dvanáct","range":"Mk 3,13–19","thoughts":[],"verses":[[13,"Ježíš vystoupil na horu a zavolal k sobě ty, které chtěl. A oni k němu přišli."],[14,"Ustanovil jich dvanáct, aby byli s ním, aby je posílal kázat"],[15,"a aby měli moc uzdravovat nemoci a vyhánět démony."],[16,"Šimona pojmenoval Petr;"],[17,"Jakuba, syna Zebedeova, a jeho bratra Jana pojmenoval Boanerges, to znamená Synové hromu;"],[18,"dále Ondřeje, Filipa, Bartoloměje, Matouše, Tomáše, Jakuba, syna Alfeova, Tadeáše, Šimona Kananejského"],[19,"a Jidáše Iškariotského, který ho později zradil. Potom vešli do domu."]]},{"title":"Ježíš a Belzebub","range":"Mk 3,20–30","thoughts":[],"verses":[[20,"Znovu se shromáždil zástup, takže se nemohli ani najíst."],[21,"Když o tom uslyšeli jeho příbuzní, vyšli, aby se ho zmocnili, protože říkali: „Pomátl se.“"],[22,"Učitelé Zákona, kteří přišli z Jeruzaléma, říkali: „Má Belzebuba“ a „Démony vyhání mocí vládce démonů.“"],[23,"Ježíš si je zavolal a mluvil k nim v podobenstvích: „Jak může satan vyhánět satana?“"],[24,"„Je-li království rozdělené samo proti sobě, nemůže takové království obstát.“"],[25,"„A je-li dům rozdělený sám proti sobě, nemůže takový dům obstát.“"],[26,"„Jestliže satan povstal sám proti sobě a je rozdělený, nemůže obstát, ale je s ním konec.“"],[27,"„Nikdo nemůže vejít do domu silného člověka a uloupit jeho věci, pokud toho silného nejprve nespoutá. Teprve potom může jeho dům vyplenit.“"],[28,"„Amen, říkám vám: Všechny hříchy budou lidským synům odpuštěny, i všechna rouhání, kterých se dopustí.“"],[29,"„Kdo by se však rouhal proti Duchu svatému, nemá odpuštění navěky, ale provinil se věčným hříchem.“"],[30,"Řekl to proto, že tvrdili: „Má nečistého ducha.“"]]},{"title":"Ježíšova pravá rodina","range":"Mk 3,31–35","thoughts":[],"verses":[[31,"Přišla jeho matka a jeho bratři. Zůstali venku a poslali pro něj."],[32,"Kolem něj seděl zástup a řekli mu: „Tvoje matka a tvoji bratři jsou venku a hledají tě.“"],[33,"Ježíš jim odpověděl: „Kdo je má matka a kdo jsou moji bratři?“"],[34,"Rozhlédl se po těch, kdo kolem něj seděli, a řekl: „Hle, má matka a moji bratři.“"],[35,"„Kdo plní Boží vůli, ten je můj bratr, má sestra i matka.“"]]}];
MARK_SECTIONS["4"] = [{"title":"Podobenství o rozsévači","range":"Mk 4,1–9","thoughts":[],"verses":[[1,"Ježíš začal znovu učit u jezera. Shromáždil se kolem něj tak velký zástup, že nastoupil na loď, posadil se v ní na vodě a lidé zůstali na břehu."],[2,"Učil je mnoha věcem pomocí podobenství. Ve svém vyučování jim řekl:"],[3,"„Poslouchejte! Rozsévač vyšel rozsévat."],[4,"Když rozséval, část semen padla podél cesty. Přiletěli ptáci a sezobali je."],[5,"Jiná semena padla na kamenitou půdu, kde nebylo mnoho zeminy. Rychle vzešla, protože půda nebyla hluboká."],[6,"Když však vyšlo slunce, rostliny se spálily a uschly, protože neměly kořeny."],[7,"Jiná semena padla mezi trní. Trní vyrostlo, zadusilo je a nepřinesla úrodu."],[8,"Další semena padla do dobré půdy. Vyrostla, sílila a přinesla úrodu — některá třicetinásobnou, jiná šedesátinásobnou a jiná stonásobnou."],[9,"Potom řekl: „Kdo má uši k slyšení, ať poslouchá.“"]]},{"title":"Proč Ježíš mluví v podobenstvích","range":"Mk 4,10–20","thoughts":[],"verses":[[10,"Když Ježíš zůstal sám, lidé kolem něj spolu s Dvanácti se ho ptali na význam podobenství."],[11,"Řekl jim: „Vám je dáno poznávat tajemství Božího království. Těm, kdo jsou venku, se však všechno předkládá v podobenstvích,"],[12,"aby se dívali, a přesto neviděli, poslouchali, a přesto nerozuměli; jinak by se obrátili a bylo by jim odpuštěno.“"],[13,"Pak jim řekl: „Nerozumíte tomuto podobenství? Jak potom porozumíte všem ostatním?"],[14,"Rozsévač rozsévá Boží slovo."],[15,"Semeno podél cesty představuje lidi, kteří slovo slyší, ale hned přichází satan a bere slovo, které do nich bylo zaseto."],[16,"Semeno na kamenité půdě představuje ty, kdo slovo slyší a hned je s radostí přijímají."],[17,"Nemají však v sobě kořen a vydrží jen nějakou dobu. Když kvůli slovu přijde soužení nebo pronásledování, rychle odpadnou."],[18,"Semeno mezi trním představuje jiné lidi, kteří slovo slyší,"],[19,"ale starosti tohoto světa, klam bohatství a touha po dalších věcech slovo zadusí, takže nepřinese úrodu."],[20,"Semeno v dobré půdě představuje ty, kdo slovo slyší, přijímají je a přinášejí úrodu — třicetinásobnou, šedesátinásobnou nebo stonásobnou.“"]]},{"title":"Lampa a míra","range":"Mk 4,21–25","thoughts":[],"verses":[[21,"Řekl jim také: „Přináší se snad lampa proto, aby se dala pod nádobu nebo pod postel? Nedává se naopak na stojan?"],[22,"Nic totiž není skryté, co by nemělo být odhaleno, ani nic utajené, co by nemělo vyjít najevo."],[23,"Kdo má uši k slyšení, ať poslouchá.“"],[24,"Dále jim řekl: „Dávejte pozor na to, co slyšíte. Jakou mírou měříte, takovou bude naměřeno vám — a ještě vám bude přidáno."],[25,"Kdo má, tomu bude dáno. Kdo nemá, tomu bude vzato i to, co má.“"]]},{"title":"Podobenství o rostoucím semeni","range":"Mk 4,26–29","thoughts":[],"verses":[[26,"Řekl také: „S Božím královstvím je to jako s člověkem, který zaseje semeno do země."],[27,"V noci spí a ráno vstává, zatímco semeno klíčí a roste, aniž ví jak."],[28,"Země přináší úrodu sama: nejprve stéblo, potom klas a nakonec zralé zrno v klasu."],[29,"Když úroda dozraje, člověk vezme srp, protože nastala žeň.“"]]},{"title":"Hořčičné zrno","range":"Mk 4,30–34","thoughts":[],"verses":[[30,"Ježíš pokračoval: „K čemu přirovnáme Boží království? Jakým podobenstvím je znázorníme?"],[31,"Je jako hořčičné zrno. Když se zaseje do země, patří k nejmenším semenům."],[32,"Když je však zaseto, vyroste a je větší než ostatní zahradní rostliny. Vytvoří velké větve, takže v jeho stínu mohou hnízdit ptáci.“"],[33,"Takovými a mnoha dalšími podobenstvími jim předával své poselství podle toho, jak mu byli schopni rozumět."],[34,"Bez podobenství k nim nemluvil. Když však byl se svými učedníky sám, všechno jim vysvětloval."]]},{"title":"Utišení bouře","range":"Mk 4,35–41","thoughts":[],"verses":[[35,"Večer toho dne jim Ježíš řekl: „Přeplavme se na druhou stranu.“"],[36,"Učedníci nechali zástup na břehu a vzali Ježíše s sebou v lodi, ve které už byl. Doprovázely je i další lodě."],[37,"Strhla se silná bouře. Vlny se přelévaly přes loď, takže se začínala plnit vodou."],[38,"Ježíš zatím spal vzadu na lodi na podušce. Probudili ho a řekli: „Mistře, je ti jedno, že zahyneme?“"],[39,"Ježíš vstal, pohrozil větru a řekl moři: „Mlč! Utiš se!“ Vítr ustal a nastal veliký klid."],[40,"Pak jim řekl: „Proč se tak bojíte? Ještě pořád nemáte víru?“"],[41,"Zmocnila se jich veliká bázeň a říkali si mezi sebou: „Kdo to vlastně je, že ho poslouchá i vítr a moře?“"]]}];

MARK_SECTIONS["5"] = [{"title":"Uzdravení posedlého v gerasenské krajině","range":"Mk 5,1–20","thoughts":[],"verses":[[1,"Přeplavili se na druhou stranu jezera do gerasenské krajiny."],[2,"Jakmile Ježíš vystoupil z lodi, vyšel mu z hrobů naproti člověk ovládaný nečistým duchem."],[3,"Žil mezi hroby a nikdo ho už nedokázal spoutat ani řetězy."],[4,"Mnohokrát ho spoutali okovy a řetězy, ale řetězy přetrhal a okovy rozbil. Nikdo neměl sílu ho zkrotit."],[5,"Ve dne i v noci se potuloval mezi hroby a po kopcích, křičel a zraňoval se kameny."],[6,"Když z dálky uviděl Ježíše, přiběhl k němu a padl před ním na zem."],[7,"Hlasitě vykřikl: „Co ode mě chceš, Ježíši, Synu nejvyššího Boha? Zapřísahám tě při Bohu, netrap mě!“"],[8,"Ježíš mu totiž říkal: „Nečistý duchu, vyjdi z toho člověka!“"],[9,"Zeptal se ho: „Jak se jmenuješ?“ Odpověděl: „Jmenuji se Legie, protože je nás mnoho.“"],[10,"A naléhavě Ježíše prosil, aby je neposílal pryč z té krajiny."],[11,"Na nedalekém svahu se páslo velké stádo prasat."],[12,"Nečistí duchové ho prosili: „Pošli nás do těch prasat, ať do nich můžeme vejít.“"],[13,"Ježíš jim to dovolil. Nečistí duchové vyšli z člověka a vstoupili do prasat. Stádo, asi dva tisíce kusů, se rozběhlo ze svahu do jezera a utopilo se."],[14,"Pasáci utekli a roznesli zprávu po městě i okolí. Lidé se přišli podívat, co se stalo."],[15,"Když přišli k Ježíšovi, uviděli člověka, který býval posedlý množstvím démonů. Seděl tam oblečený a při zdravém rozumu. Lidé dostali strach."],[16,"Ti, kdo událost viděli, jim vyprávěli, co se stalo s posedlým člověkem i s prasaty."],[17,"Lidé pak začali Ježíše prosit, aby z jejich kraje odešel."],[18,"Když Ježíš nastupoval do lodi, muž, který byl předtím posedlý, ho prosil, aby mohl jít s ním."],[19,"Ježíš mu to však nedovolil a řekl: „Jdi domů ke svým blízkým a vyprávěj jim, co pro tebe Pán udělal a jak se nad tebou slitoval.“"],[20,"Muž odešel a začal v Desetiměstí vyprávět, co pro něj Ježíš udělal. Všichni nad tím žasli."]]},{"title":"Jairova prosba a žena s krvácením","range":"Mk 5,21–34","thoughts":[],"verses":[[21,"Když se Ježíš lodí vrátil na druhou stranu, shromáždil se kolem něj velký zástup. Ježíš zůstal u jezera."],[22,"Přišel k němu jeden z představených synagogy jménem Jair. Jakmile Ježíše uviděl, padl mu k nohám."],[23,"Naléhavě ho prosil: „Moje malá dcera umírá. Pojď, polož na ni ruce, aby se uzdravila a žila.“"],[24,"Ježíš šel s ním. Následoval ho velký zástup a lidé se na něj tlačili ze všech stran."],[25,"Byla tam také žena, která už dvanáct let trpěla krvácením."],[26,"Mnoho vytrpěla od různých lékařů a utratila za léčbu všechno, co měla. Nic jí však nepomohlo a její stav se stále zhoršoval."],[27,"Když se doslechla o Ježíšovi, přišla v zástupu zezadu a dotkla se jeho oděvu."],[28,"Říkala si totiž: „Když se dotknu třeba jen jeho oděvu, uzdravím se.“"],[29,"Krvácení okamžitě přestalo a ona na svém těle poznala, že je ze své nemoci uzdravena."],[30,"Ježíš hned poznal, že z něj vyšla moc. Obrátil se v zástupu a zeptal se: „Kdo se dotkl mého oděvu?“"],[31,"Jeho učedníci mu řekli: „Vidíš, jak se na tebe tlačí zástup, a ptáš se, kdo se tě dotkl?“"],[32,"Ježíš se však rozhlížel, aby uviděl toho, kdo to udělal."],[33,"Žena věděla, co se s ní stalo. Se strachem a chvěním přišla, padla před ním a řekla mu celou pravdu."],[34,"Ježíš jí řekl: „Dcero, tvá víra tě zachránila. Jdi v pokoji a buď zbavena svého trápení.“"]]},{"title":"Vzkříšení Jairovy dcery","range":"Mk 5,35–43","thoughts":[],"verses":[[35,"Ještě když Ježíš mluvil, přišli lidé z domu představeného synagogy a řekli: „Tvá dcera zemřela. Proč ještě obtěžovat Mistra?“"],[36,"Ježíš jejich slova zaslechl a řekl Jairovi: „Neboj se, jen věř.“"],[37,"Nedovolil nikomu, aby šel s ním, kromě Petra, Jakuba a Jakubova bratra Jana."],[38,"Když přišli k Jairovu domu, Ježíš viděl rozruch a lidi, kteří hlasitě plakali a naříkali."],[39,"Vešel dovnitř a řekl jim: „Proč děláte takový rozruch a pláčete? Dítě nezemřelo, ale spí.“"],[40,"Lidé se mu vysmívali. Ježíš je všechny poslal ven, vzal s sebou otce a matku dítěte a své tři učedníky a vešel tam, kde dívka ležela."],[41,"Vzal ji za ruku a řekl: „Talitha kum,“ což znamená: „Děvče, říkám ti, vstaň!“"],[42,"Dívka okamžitě vstala a začala chodit. Bylo jí dvanáct let. Všichni byli ohromeni."],[43,"Ježíš jim důrazně přikázal, aby se o tom nikdo nedozvěděl, a řekl, aby jí dali něco k jídlu."]]}];

MARK_SECTIONS["6"] = [{"title":"Ježíš v Nazaretě","range":"Mk 6,1–6","thoughts":[],"verses":[[1,"Ježíš odtud odešel do svého rodného kraje a jeho učedníci šli s ním."],[2,"Když přišla sobota, začal učit v synagoze. Mnozí posluchači žasli a ptali se: „Odkud to všechno má? Jaká moudrost mu byla dána? A jak je možné, že jeho rukama se dějí takové mocné činy?“"],[3,"„Není to snad ten tesař, syn Marie a bratr Jakuba, Josese, Judy a Šimona? A nežijí tady mezi námi i jeho sestry?“ A odmítali ho přijmout."],[4,"Ježíš jim řekl: „Prorok bývá bez úcty jen ve svém rodném kraji, mezi svými příbuznými a ve svém domě.“"],[5,"Nemohl tam vykonat žádný velký zázrak, jen položil ruce na několik nemocných a uzdravil je."],[6,"Podivoval se jejich nevěře. Potom chodil po okolních vesnicích a učil."]]},{"title":"Vyslání Dvanácti","range":"Mk 6,7–13","thoughts":[],"verses":[[7,"Zavolal k sobě Dvanáct a začal je posílat po dvou. Dal jim moc nad nečistými duchy."],[8,"Přikázal jim, aby si na cestu kromě hole nic nebrali — ani chléb, ani tašku, ani peníze do opasku."],[9,"Měli mít sandály, ale neměli si brát náhradní oděv."],[10,"Řekl jim: „Když někde vstoupíte do domu, zůstaňte tam, dokud z toho místa neodejdete."],[11,"A pokud vás někde nepřijmou ani vás nebudou chtít poslouchat, při odchodu setřeste prach ze svých nohou na svědectví proti nim.“"],[12,"Učedníci tedy vyšli a hlásali lidem, aby činili pokání."],[13,"Vyháněli mnoho démonů, pomazávali olejem mnoho nemocných a uzdravovali je."]]},{"title":"Smrt Jana Křtitele","range":"Mk 6,14–29","thoughts":[],"verses":[[14,"O Ježíšovi se doslechl i král Herodes, protože jeho jméno už bylo všeobecně známé. Někteří říkali: „Jan Křtitel vstal z mrtvých, a proto skrze něj působí takové mocné síly.“"],[15,"Jiní říkali: „Je to Eliáš.“ A další: „Je to prorok jako jeden z dávných proroků.“"],[16,"Když to Herodes uslyšel, řekl: „Jan, kterého jsem nechal stít, vstal z mrtvých.“"],[17,"Herodes totiž předtím nechal Jana zatknout, spoutat a uvěznit kvůli Herodiadě, ženě svého bratra Filipa, kterou si vzal za manželku."],[18,"Jan mu totiž říkal: „Není dovoleno, abys měl manželku svého bratra.“"],[19,"Herodias proto Jana nenáviděla a chtěla ho zabít, ale nemohla."],[20,"Herodes se totiž Jana bál. Věděl, že je to spravedlivý a svatý člověk, a proto ho chránil. Když ho poslouchal, býval velmi rozpačitý, přesto mu naslouchal rád."],[21,"Příležitost se naskytla v den Herodových narozenin. Herodes uspořádal hostinu pro své vysoké úředníky, velitele a přední muže Galileje."],[22,"Když přišla Herodiadina dcera a zatančila, Herodovi i jeho hostům se zalíbila. Král jí řekl: „Požádej mě, o cokoli chceš, a já ti to dám.“"],[23,"Dokonce jí přísahal: „O cokoli mě požádáš, dám ti to, třeba polovinu svého království.“"],[24,"Dívka vyšla ven a zeptala se matky: „O co mám požádat?“ Ta odpověděla: „O hlavu Jana Křtitele.“"],[25,"Dívka se hned vrátila ke králi a řekla: „Chci, abys mi teď hned dal na míse hlavu Jana Křtitele.“"],[26,"Král se velmi zarmoutil, ale kvůli přísaze a hostům ji nechtěl odmítnout."],[27,"Okamžitě tedy poslal kata s rozkazem přinést Janovu hlavu."],[28,"Kat odešel, ve vězení Jana sťal, přinesl jeho hlavu na míse a dal ji dívce. Dívka ji pak dala své matce."],[29,"Když se o tom dozvěděli Janovi učedníci, přišli, vzali jeho tělo a uložili je do hrobu."]]},{"title":"Návrat apoštolů a nasycení pěti tisíc","range":"Mk 6,30–44","thoughts":[],"verses":[[30,"Apoštolové se vrátili k Ježíšovi a vyprávěli mu všechno, co dělali a co učili."],[31,"Ježíš jim řekl: „Pojďte sami stranou na opuštěné místo a trochu si odpočiňte.“ Přicházelo a odcházelo totiž tolik lidí, že neměli ani čas se najíst."],[32,"Odpluli tedy lodí na opuštěné místo, aby byli sami."],[33,"Mnoho lidí je však vidělo odjíždět a poznalo je. Z okolních měst se tam pěšky seběhli a dorazili před nimi."],[34,"Když Ježíš vystoupil z lodi, uviděl velký zástup. Bylo mu jich líto, protože byli jako ovce bez pastýře. Začal je proto učit mnoha věcem."],[35,"Když už bylo pozdě, přišli k němu učedníci a řekli: „Je tu pusto a je už hodně pozdě."],[36,"Pošli lidi pryč, ať si v okolních vesnicích a osadách koupí něco k jídlu.“"],[37,"Ježíš jim odpověděl: „Dejte jim najíst vy.“ Zeptali se: „Máme snad jít nakoupit chleba za dvě stě denárů a dát jim najíst?“"],[38,"Řekl jim: „Kolik máte chlebů? Jděte se podívat.“ Když to zjistili, odpověděli: „Pět chlebů a dvě ryby.“"],[39,"Ježíš jim nařídil, aby všechny usadili po skupinách na zelené trávě."],[40,"Lidé se posadili ve skupinách po stu a po padesáti."],[41,"Ježíš vzal pět chlebů a dvě ryby, vzhlédl k nebi, pronesl požehnání, lámal chleby a dával je učedníkům, aby je rozdávali lidem. Také dvě ryby rozdělil mezi všechny."],[42,"Všichni se najedli dosyta."],[43,"Potom sesbírali dvanáct plných košů zbylých kousků chleba a ryb."],[44,"Těch, kdo jedli chleby, bylo asi pět tisíc mužů."]]},{"title":"Ježíš kráčí po moři","range":"Mk 6,45–52","thoughts":[],"verses":[[45,"Hned potom Ježíš přiměl učedníky, aby nastoupili do lodi a jeli před ním na druhou stranu směrem k Betsaidě, zatímco on propustí zástup."],[46,"Když se s lidmi rozloučil, odešel na horu, aby se modlil."],[47,"Večer byla loď uprostřed jezera a Ježíš zůstal sám na břehu."],[48,"Viděl, jak se učedníci při veslování namáhají, protože vítr foukal proti nim. K ránu k nim přišel po hladině jezera a zdálo se, jako by je chtěl minout."],[49,"Když ho uviděli kráčet po vodě, mysleli si, že je to přízrak, a vykřikli."],[50,"Všichni ho totiž viděli a vyděsili se. Ježíš na ně hned promluvil: „Buďte klidní, to jsem já. Nebojte se!“"],[51,"Nastoupil k nim do lodi a vítr ustal. Učedníci byli úplně ohromeni."],[52,"Stále totiž nepochopili, co znamenalo rozmnožení chlebů; jejich srdce zůstávalo nechápavé."]]},{"title":"Uzdravování v Genezaretu","range":"Mk 6,53–56","thoughts":[],"verses":[[53,"Přeplavili se na druhou stranu, dorazili do Genezaretu a přistáli."],[54,"Jakmile vystoupili z lodi, lidé Ježíše poznali."],[55,"Rozběhli se po celém okolí a začali na nosítkách přinášet nemocné všude tam, kde se doslechli, že Ježíš je."],[56,"Kamkoli přišel — do vesnic, měst nebo osad — pokládali nemocné na veřejná místa a prosili ho, aby se mohli dotknout alespoň okraje jeho oděvu. A všichni, kdo se ho dotkli, byli uzdraveni."]]}];

MARK_SECTIONS["7"] = [{"title":"Tradice a Boží přikázání","range":"Mk 7,1–13","thoughts":[],"verses":[[1,"K Ježíšovi se shromáždili farizeové a někteří učitelé Zákona, kteří přišli z Jeruzaléma."],[2,"Všimli si, že někteří jeho učedníci jedí chléb neobřadně umytýma rukama."],[3,"Farizeové a Židé obecně totiž podle tradice předků nejedli, dokud si obřadně neumyli ruce."],[4,"Když se vrátili z tržiště, nejedli, dokud se neočistili. Zachovávali také mnoho dalších převzatých zvyků, například obřadné omývání pohárů, nádob a dalšího náčiní."],[5,"Farizeové a učitelé Zákona se ho proto zeptali: „Proč se tvoji učedníci neřídí tradicí předků a jedí neobřadně umytýma rukama?“"],[6,"Ježíš jim odpověděl: „Izaiáš o vás pokrytcích prorokoval správně, když napsal: Tento lid mě ctí rty, ale jejich srdce je ode mě daleko."],[7,"Uctívají mě však nadarmo, protože jako nauku předkládají lidská pravidla."],[8,"Opouštíte Boží přikázání a držíte se lidské tradice.“"],[9,"A pokračoval: „Umíte pěkně odsunout Boží přikázání, abyste mohli zachovat vlastní tradici."],[10,"Mojžíš přece řekl: Cti svého otce i matku; a také: Kdo zlořečí otci nebo matce, musí zemřít."],[11,"Vy však říkáte: Když člověk řekne otci nebo matce: To, čím bych ti mohl pomoci, je korban, tedy dar určený Bohu,"],[12,"už mu nedovolíte, aby pro svého otce nebo matku něco udělal."],[13,"Tak svou tradicí, kterou předáváte dál, rušíte Boží slovo. A podobných věcí děláte mnoho.“"]]},{"title":"Co člověka znečišťuje","range":"Mk 7,14–23","thoughts":[],"verses":[[14,"Ježíš znovu zavolal zástup a řekl: „Poslouchejte mě všichni a snažte se tomu porozumět."],[15,"Člověka nemůže znečistit nic, co do něj přichází zvenčí. Znečišťuje ho to, co vychází z jeho nitra."],[16,"Kdo má uši k slyšení, ať poslouchá.“"],[17,"Když potom odešel od zástupu do domu, učedníci se ho na význam tohoto výroku ptali."],[18,"Řekl jim: „Ani vy tomu ještě nerozumíte? Nechápete, že nic, co přichází do člověka zvenčí, ho nemůže vnitřně znečistit?"],[19,"Nevstupuje to do jeho srdce, ale do žaludku a potom odchází z těla.“ Tím prohlásil všechny pokrmy za čisté."],[20,"Pokračoval: „Člověka znečišťuje to, co vychází z jeho nitra."],[21,"Z lidského srdce totiž vycházejí zlé myšlenky, sexuální nemravnost, krádeže, vraždy,"],[22,"cizoložství, chamtivost, zloba, podvod, nestoudnost, závist, urážky Boha, pýcha a nerozumnost."],[23,"Všechno toto zlo vychází zevnitř a znečišťuje člověka.“"]]},{"title":"Víra syrofénické ženy","range":"Mk 7,24–30","thoughts":[],"verses":[[24,"Ježíš odtud odešel do okolí Týru. Vstoupil do jednoho domu a nechtěl, aby se o něm někdo dozvěděl, ale nepodařilo se mu zůstat v skrytu."],[25,"Doslechla se o něm žena, jejíž malá dcera byla ovládána nečistým duchem. Přišla a padla mu k nohám."],[26,"Byla to pohanka, původem Syroféničanka. Prosila Ježíše, aby z její dcery vyhnal démona."],[27,"Ježíš jí řekl: „Nech nejprve nasytit děti. Není správné vzít chléb dětem a hodit ho psíkům.“"],[28,"Odpověděla mu: „Ano, Pane. Ale i psíci pod stolem jedí drobky, které padají dětem.“"],[29,"Ježíš jí řekl: „Kvůli této odpovědi můžeš jít domů. Démon z tvé dcery vyšel.“"],[30,"Když přišla domů, našla dítě ležet na lůžku a démon byl pryč."]]},{"title":"Uzdravení hluchoněmého","range":"Mk 7,31–37","thoughts":[],"verses":[[31,"Ježíš potom opustil okolí Týru, prošel přes Sidón a územím Desetiměstí přišel ke Galilejskému jezeru."],[32,"Přivedli k němu člověka, který byl hluchý a špatně mluvil, a prosili Ježíše, aby na něj položil ruku."],[33,"Ježíš si ho vzal stranou od zástupu. Vložil mu prsty do uší, dotkl se slinou jeho jazyka,"],[34,"vzhlédl k nebi, povzdechl si a řekl mu: „Effatha!“ To znamená: „Otevři se!“"],[35,"V tu chvíli se mu otevřel sluch, uvolnil se mu jazyk a začal správně mluvit."],[36,"Ježíš lidem přikázal, aby o tom nikomu neříkali. Čím víc jim to však zakazoval, tím víc o tom mluvili."],[37,"Byli nesmírně ohromeni a říkali: „Všechno udělal dobře. Dokonce i hluchým dává slyšet a němým mluvit.“"]]}];

MARK_SECTIONS["8"] = [{"title":"Nasycení čtyř tisíc","range":"Mk 8,1–10","thoughts":[],"verses":[[1,"V těch dnech se znovu shromáždil velký zástup a lidé neměli co jíst. Ježíš zavolal své učedníky a řekl jim:"],[2,"„Je mi těch lidí líto. Už tři dny jsou se mnou a nemají co jíst."],[3,"Kdybych je poslal domů hladové, cestou zeslábnou. Někteří z nich totiž přišli zdaleka.“"],[4,"Učedníci mu odpověděli: „Kde by tady v pustině mohl někdo sehnat tolik chleba, aby všechny nasytil?“"],[5,"Ježíš se jich zeptal: „Kolik máte chlebů?“ Odpověděli: „Sedm.“"],[6,"Nařídil zástupu, aby se posadil na zem. Vzal sedm chlebů, poděkoval Bohu, lámal je a dával učedníkům, aby je rozdávali. A oni je rozdávali lidem."],[7,"Měli také několik malých ryb. Ježíš nad nimi pronesl požehnání a řekl, aby rozdali i je."],[8,"Všichni se najedli dosyta. Ze zbylých kousků potom naplnili sedm košů."],[9,"Bylo tam asi čtyři tisíce lidí. Potom je Ježíš propustil."],[10,"Hned nastoupil se svými učedníky do lodi a odplul do dalmanutské oblasti."]]},{"title":"Farizeové žádají znamení","range":"Mk 8,11–13","thoughts":[],"verses":[[11,"Přišli farizeové a začali se s Ježíšem přít. Chtěli ho zkoušet, a proto po něm žádali znamení z nebe."],[12,"Ježíš si hluboce povzdechl a řekl: „Proč toto pokolení žádá znamení? Amen, říkám vám: Tomuto pokolení žádné znamení dáno nebude.“"],[13,"Potom je opustil, znovu nastoupil do lodi a odplul na druhou stranu."]]},{"title":"Varování před kvasem","range":"Mk 8,14–21","thoughts":[],"verses":[[14,"Učedníci si zapomněli vzít chléb a v lodi měli s sebou jen jeden bochník."],[15,"Ježíš je varoval: „Dávejte si pozor na kvas farizeů a na kvas Heroda.“"],[16,"Učedníci se mezi sebou bavili o tom, že nemají chléb."],[17,"Ježíš to věděl a řekl jim: „Proč řešíte, že nemáte chléb? Ještě nechápete a nerozumíte? Je vaše srdce stále tak nechápavé?"],[18,"Máte oči, a nevidíte? Máte uši, a neslyšíte? Copak si nevzpomínáte?"],[19,"Když jsem rozdělil pět chlebů mezi pět tisíc lidí, kolik plných košů zbytků jste sebrali?“ Odpověděli: „Dvanáct.“"],[20,"„A když jsem rozdělil sedm chlebů mezi čtyři tisíce, kolik plných košů zbytků jste sebrali?“ Odpověděli: „Sedm.“"],[21,"Řekl jim: „Tak ještě pořád nerozumíte?“"]]},{"title":"Uzdravení slepého v Betsaidě","range":"Mk 8,22–26","thoughts":[],"verses":[[22,"Přišli do Betsaidy. Lidé k Ježíšovi přivedli slepého člověka a prosili ho, aby se ho dotkl."],[23,"Ježíš vzal slepého za ruku a vyvedl ho ven z vesnice. Potom mu potřel oči slinou, položil na něj ruce a zeptal se: „Vidíš něco?“"],[24,"Muž se rozhlédl a řekl: „Vidím lidi, ale vypadají jako chodící stromy.“"],[25,"Ježíš mu znovu položil ruce na oči. Muž se pozorně podíval, jeho zrak se obnovil a všechno viděl jasně."],[26,"Ježíš ho poslal domů a řekl mu: „Do vesnice se nevracej.“"]]},{"title":"Petrovo vyznání","range":"Mk 8,27–30","thoughts":[],"verses":[[27,"Ježíš se svými učedníky odešel do vesnic v okolí Cesareje Filipovy. Cestou se jich zeptal: „Za koho mě lidé považují?“"],[28,"Odpověděli: „Za Jana Křtitele, jiní za Eliáše a další za jednoho z proroků.“"],[29,"Zeptal se jich: „A za koho mě považujete vy?“ Petr mu odpověděl: „Ty jsi Kristus.“"],[30,"Ježíš jim důrazně přikázal, aby o něm nikomu neříkali."]]},{"title":"První předpověď utrpení","range":"Mk 8,31–33","thoughts":[],"verses":[[31,"Potom je začal učit, že Syn člověka musí mnoho trpět, být odmítnut staršími, předními kněžími a učiteli Zákona, být zabit a po třech dnech vstát z mrtvých."],[32,"Mluvil o tom zcela otevřeně. Petr si ho vzal stranou a začal mu to rozmlouvat."],[33,"Ježíš se však obrátil, podíval se na své učedníky a Petra pokáral: „Jdi za mě, satane! Nemyslíš na to, co chce Bůh, ale na to, co chtějí lidé.“"]]},{"title":"Následování a kříž","range":"Mk 8,34–38","thoughts":[],"verses":[[34,"Potom zavolal zástup i své učedníky a řekl jim: „Kdo chce jít za mnou, ať zapře sám sebe, vezme svůj kříž a následuje mě."],[35,"Kdo by si chtěl zachránit život, ztratí ho. Kdo však svůj život ztratí kvůli mně a evangeliu, zachrání ho."],[36,"Co člověku prospěje, když získá celý svět, ale ztratí svůj život?"],[37,"A co může člověk dát výměnou za svůj život?"],[38,"Kdo se bude stydět za mě a za má slova v tomto nevěrném a hříšném pokolení, za toho se bude stydět i Syn člověka, až přijde ve slávě svého Otce se svatými anděly.“"]]}];

MARK_SECTIONS["9"] = [{"title":"Proměnění na hoře","range":"Mk 9,1–13","thoughts":[],"verses":[[1,"Ježíš jim řekl: „Amen, říkám vám: Někteří z těch, kdo tu stojí, nezemřou dříve, než uvidí Boží království přicházet v moci.“"],[2,"Po šesti dnech vzal Ježíš Petra, Jakuba a Jana a odvedl je samotné na vysokou horu. Tam se před nimi proměnil."],[3,"Jeho oděv začal zářit a byl oslnivě bílý, bělejší, než by jej dokázal vybělit kdokoli na zemi."],[4,"Ukázali se jim Eliáš a Mojžíš a rozmlouvali s Ježíšem."],[5,"Petr Ježíšovi řekl: „Mistře, je dobře, že jsme tady. Postavme tři stany: jeden pro tebe, jeden pro Mojžíše a jeden pro Eliáše.“"],[6,"Nevěděl totiž, co říct, protože byli velmi vyděšení."],[7,"Objevil se oblak a zahalil je. Z oblaku zazněl hlas: „Toto je můj milovaný Syn. Poslouchejte ho.“"],[8,"Když se náhle rozhlédli, nikoho už kolem sebe neviděli, jen Ježíše."],[9,"Když sestupovali z hory, Ježíš jim přikázal, aby nikomu nevyprávěli, co viděli, dokud Syn člověka nevstane z mrtvých."],[10,"Toho se drželi, ale mezi sebou přemýšleli, co znamená vstát z mrtvých."],[11,"Zeptali se ho: „Proč učitelé Zákona říkají, že nejprve musí přijít Eliáš?“"],[12,"Ježíš odpověděl: „Eliáš opravdu přichází nejprve a všechno napraví. Ale proč je o Synu člověka napsáno, že musí mnoho trpět a být zavržen?"],[13,"Říkám vám, že Eliáš už přišel a lidé s ním udělali, co chtěli, jak je o něm napsáno.“"]]},{"title":"Uzdravení posedlého chlapce","range":"Mk 9,14–29","thoughts":[],"verses":[[14,"Když se vrátili k ostatním učedníkům, uviděli kolem nich velký zástup a učitele Zákona, kteří se s nimi přeli."],[15,"Jakmile lidé Ježíše uviděli, byli překvapeni, rozběhli se k němu a vítali ho."],[16,"Ježíš se zeptal: „O čem se s nimi přete?“"],[17,"Jeden muž ze zástupu odpověděl: „Mistře, přivedl jsem k tobě svého syna. Je ovládán duchem, který mu brání mluvit."],[18,"Kdykoli se ho zmocní, srazí ho k zemi. Chlapec má pěnu u úst, skřípe zuby a ztuhne. Prosil jsem tvé učedníky, aby toho ducha vyhnali, ale nedokázali to.“"],[19,"Ježíš odpověděl: „Nevěřící pokolení! Jak dlouho ještě budu s vámi? Jak dlouho vás budu snášet? Přiveďte ho ke mně.“"],[20,"Přivedli chlapce k Ježíšovi. Jakmile ho duch uviděl, začal chlapcem prudce zmítat. Ten padl na zem, válel se a měl pěnu u úst."],[21,"Ježíš se jeho otce zeptal: „Jak dlouho se mu to děje?“ Odpověděl: „Od dětství."],[22,"Často ho ten duch hází do ohně i do vody, aby ho zabil. Jestli můžeš něco udělat, slituj se nad námi a pomoz nám.“"],[23,"Ježíš mu řekl: „Jestli můžeš? Všechno je možné tomu, kdo věří.“"],[24,"Chlapcův otec okamžitě zvolal: „Věřím! Pomoz mé nedostatečné víře!“"],[25,"Když Ježíš viděl, že se sbíhá další zástup, pohrozil nečistému duchu: „Němý a hluchý duchu, přikazuji ti: Vyjdi z něj a už se do něj nevracej!“"],[26,"Duch vykřikl, prudce chlapcem zalomcoval a vyšel z něj. Chlapec zůstal ležet jako mrtvý, takže mnozí říkali: „Zemřel.“"],[27,"Ježíš ho však vzal za ruku, zvedl ho a chlapec se postavil."],[28,"Když potom Ježíš vešel do domu, učedníci se ho v soukromí zeptali: „Proč jsme ho nedokázali vyhnat my?“"],[29,"Odpověděl jim: „Tento druh nelze vyhnat ničím jiným než modlitbou.“"]]},{"title":"Druhá předpověď utrpení","range":"Mk 9,30–32","thoughts":[],"verses":[[30,"Odtud odešli a procházeli Galilejí. Ježíš nechtěl, aby se o jejich cestě někdo dozvěděl,"],[31,"protože učil své učedníky. Říkal jim: „Syn člověka bude vydán do rukou lidí. Zabijí ho, ale tři dny po své smrti vstane z mrtvých.“"],[32,"Učedníci jeho slovům nerozuměli a báli se ho zeptat."]]},{"title":"Kdo je největší","range":"Mk 9,33–37","thoughts":[],"verses":[[33,"Přišli do Kafarnaum. Když byli v domě, Ježíš se jich zeptal: „O čem jste se cestou dohadovali?“"],[34,"Oni však mlčeli, protože se cestou přeli o to, kdo z nich je největší."],[35,"Ježíš se posadil, zavolal Dvanáct a řekl jim: „Kdo chce být první, musí být poslední ze všech a služebníkem všech.“"],[36,"Potom vzal malé dítě, postavil je doprostřed nich, objal je a řekl:"],[37,"„Kdo přijme jedno takové dítě v mém jménu, přijímá mě. A kdo přijímá mě, nepřijímá jen mě, ale toho, který mě poslal.“"]]},{"title":"Kdo není proti nám, je s námi","range":"Mk 9,38–41","thoughts":[],"verses":[[38,"Jan mu řekl: „Mistře, viděli jsme někoho, kdo ve tvém jménu vyháněl démony. Bránili jsme mu v tom, protože nepatří k nám.“"],[39,"Ježíš odpověděl: „Nebraňte mu. Nikdo, kdo v mém jménu vykoná mocný čin, nebude hned potom o mně mluvit zle."],[40,"Kdo není proti nám, je s námi."],[41,"A kdo vám dá napít třeba jen pohár vody proto, že patříte Kristu, amen, říkám vám: O svou odměnu nepřijde.“"]]},{"title":"Pohoršení a radikální věrnost","range":"Mk 9,42–50","thoughts":[],"verses":[[42,"„Kdo by svedl k hříchu jednoho z těchto maličkých, kteří ve mě věří, pro toho by bylo lépe, kdyby mu na krk pověsili velký mlýnský kámen a hodili ho do moře."],[43,"Jestli tě tvá ruka svádí k hříchu, usekni ji. Je pro tebe lepší vejít do života bez jedné ruky než mít obě ruce a skončit v pekle, v neuhasitelném ohni."],[44,"Tam jejich červ neumírá a oheň nehasne."],[45,"Jestli tě tvá noha svádí k hříchu, usekni ji. Je pro tebe lepší vejít do života chromý než mít obě nohy a být uvržen do pekla."],[46,"Tam jejich červ neumírá a oheň nehasne."],[47,"A jestli tě tvé oko svádí k hříchu, zbav se ho. Je pro tebe lepší vejít do Božího království s jedním okem než mít obě oči a být uvržen do pekla,"],[48,"kde jejich červ neumírá a oheň nehasne."],[49,"Každý totiž bude osolen ohněm."],[50,"Sůl je dobrá. Když však ztratí slanost, čím ji znovu osolíte? Mějte sůl v sobě a žijte mezi sebou v pokoji.“"]]}];

MARK_SECTIONS["10"] = [{"title":"O manželství a rozvodu","range":"Mk 10,1–12","thoughts":[],"verses":[[1,"Ježíš odtud odešel do judského kraje a na území za Jordánem. Znovu se kolem něj shromáždily zástupy a on je jako obvykle učil."],[2,"Přišli k němu farizeové a chtěli ho zkoušet. Zeptali se: „Smí muž propustit svou manželku?“"],[3,"Ježíš jim odpověděl: „Co vám přikázal Mojžíš?“"],[4,"Řekli: „Mojžíš dovolil napsat rozvodový list a ženu propustit.“"],[5,"Ježíš jim řekl: „Toto ustanovení vám napsal kvůli tvrdosti vašeho srdce."],[6,"Od počátku stvoření je však Bůh stvořil jako muže a ženu."],[7,"Proto muž opustí svého otce i matku a spojí se se svou ženou,"],[8,"a ti dva budou jedno tělo. Už tedy nejsou dva, ale jedno."],[9,"Co tedy Bůh spojil, člověk ať nerozděluje.“"],[10,"Když byli potom v domě, učedníci se ho na to znovu ptali."],[11,"Ježíš jim řekl: „Kdo propustí svou manželku a vezme si jinou, dopouští se vůči ní cizoložství."],[12,"A jestliže žena opustí svého muže a provdá se za jiného, dopouští se cizoložství.“"]]},{"title":"Ježíš žehná dětem","range":"Mk 10,13–16","thoughts":[],"verses":[[13,"Lidé k Ježíšovi přinášeli děti, aby se jich dotkl, ale učedníci je napomínali."],[14,"Když to Ježíš uviděl, rozhořčilo ho to. Řekl jim: „Nechte děti přicházet ke mně a nebraňte jim, protože právě takovým patří Boží království."],[15,"Amen, říkám vám: Kdo nepřijme Boží království jako dítě, vůbec do něj nevejde.“"],[16,"Potom děti bral do náruče, pokládal na ně ruce a žehnal jim."]]},{"title":"Bohatý muž","range":"Mk 10,17–31","thoughts":[],"verses":[[17,"Když se Ježíš vydával na cestu, přiběhl k němu jeden muž, poklekl před ním a zeptal se: „Dobrý Mistře, co mám dělat, abych získal věčný život?“"],[18,"Ježíš mu řekl: „Proč mě nazýváš dobrým? Nikdo není dobrý kromě jediného Boha."],[19,"Přikázání znáš: Nezabiješ, nezcizoložíš, nebudeš krást, nebudeš křivě svědčit, nebudeš podvádět, cti svého otce i matku.“"],[20,"Muž mu odpověděl: „Mistře, to všechno dodržuji od mládí.“"],[21,"Ježíš se na něj podíval s láskou a řekl: „Jedno ti ještě chybí. Jdi, prodej všechno, co máš, rozdej to chudým a budeš mít poklad v nebi. Potom přijď a následuj mě.“"],[22,"Muž se nad těmi slovy zachmuřil a smutný odešel, protože měl velký majetek."],[23,"Ježíš se rozhlédl kolem a řekl svým učedníkům: „Jak těžko budou bohatí vstupovat do Božího království!“"],[24,"Učedníky jeho slova překvapila. Ježíš jim však znovu řekl: „Děti, jak těžké je vstoupit do Božího království!"],[25,"Snadněji projde velbloud uchem jehly, než bohatý člověk vstoupí do Božího království.“"],[26,"Učedníci byli ještě více ohromeni a říkali si: „Kdo tedy může být zachráněn?“"],[27,"Ježíš se na ně podíval a řekl: „Pro lidi je to nemožné, ale ne pro Boha. Pro Boha je možné všechno.“"],[28,"Petr mu řekl: „Podívej, my jsme všechno opustili a šli za tebou.“"],[29,"Ježíš odpověděl: „Amen, říkám vám: Nikdo, kdo kvůli mně a evangeliu opustil dům, bratry, sestry, matku, otce, děti nebo pole,"],[30,"nezůstane bez odměny. Už nyní dostane stokrát více domů, bratrů, sester, matek, dětí a polí — spolu s pronásledováním — a v budoucím věku věčný život."],[31,"Mnozí první však budou poslední a poslední první.“"]]},{"title":"Třetí předpověď utrpení","range":"Mk 10,32–34","thoughts":[],"verses":[[32,"Byli na cestě do Jeruzaléma a Ježíš šel před nimi. Učedníci byli znepokojeni a ostatní, kteří je následovali, se báli. Ježíš si znovu vzal Dvanáct stranou a začal jim říkat, co ho čeká:"],[33,"„Jdeme do Jeruzaléma. Syn člověka bude vydán předním kněžím a učitelům Zákona. Odsoudí ho k smrti a vydají ho pohanům."],[34,"Budou se mu posmívat, plivat na něj, bičovat ho a nakonec ho zabijí. Po třech dnech však vstane z mrtvých.“"]]},{"title":"Prosba Jakuba a Jana","range":"Mk 10,35–45","thoughts":[],"verses":[[35,"Přišli k němu Jakub a Jan, synové Zebedeovi, a řekli: „Mistře, chtěli bychom, abys nám splnil jednu prosbu.“"],[36,"Ježíš se zeptal: „Co chcete, abych pro vás udělal?“"],[37,"Odpověděli: „Dovol nám, abychom v tvé slávě seděli jeden po tvé pravici a druhý po levici.“"],[38,"Ježíš jim řekl: „Nevíte, o co žádáte. Dokážete pít kalich, který piji já, a podstoupit křest, který podstupuji já?“"],[39,"Odpověděli: „Dokážeme.“ Ježíš jim řekl: „Kalich, který piji, opravdu budete pít a křtem, kterým procházím, projdete i vy."],[40,"Ale rozhodovat o tom, kdo bude sedět po mé pravici nebo levici, mi nepřísluší. Ta místa patří těm, pro které jsou připravena.“"],[41,"Když to uslyšelo ostatních deset, začali se na Jakuba a Jana zlobit."],[42,"Ježíš je zavolal k sobě a řekl: „Víte, že ti, kdo jsou považováni za vládce národů, nad nimi panují a jejich mocní nad nimi uplatňují svou moc."],[43,"Mezi vámi to tak být nemá. Kdo chce být mezi vámi velký, ať je vaším služebníkem."],[44,"A kdo chce být mezi vámi první, ať je služebníkem všech."],[45,"Vždyť ani Syn člověka nepřišel proto, aby si nechal sloužit, ale aby sloužil a dal svůj život jako výkupné za mnohé.“"]]},{"title":"Uzdravení slepého Bartimea","range":"Mk 10,46–52","thoughts":[],"verses":[[46,"Přišli do Jericha. Když Ježíš se svými učedníky a velkým zástupem z města odcházel, seděl u cesty slepý žebrák Bartimeus, syn Timeův."],[47,"Když uslyšel, že jde kolem Ježíš Nazaretský, začal volat: „Ježíši, Synu Davidův, smiluj se nade mnou!“"],[48,"Mnozí ho napomínali, aby mlčel. On však volal ještě hlasitěji: „Synu Davidův, smiluj se nade mnou!“"],[49,"Ježíš se zastavil a řekl: „Zavolejte ho.“ Lidé zavolali slepého a řekli mu: „Vzchop se, vstaň, volá tě.“"],[50,"Bartimeus odhodil plášť, vyskočil a přišel k Ježíšovi."],[51,"Ježíš se ho zeptal: „Co chceš, abych pro tebe udělal?“ Slepý odpověděl: „Mistře, chci znovu vidět.“"],[52,"Ježíš mu řekl: „Jdi, tvá víra tě zachránila.“ Bartimeus okamžitě prohlédl a šel za Ježíšem po cestě."]]}];

MARK_SECTIONS["11"] = [{"title":"Vjezd do Jeruzaléma","range":"Mk 11,1–11","thoughts":[],"verses":[[1,"Když se přiblížili k Jeruzalému a dorazili k Betfage a Betanii u Olivové hory, Ježíš poslal dva ze svých učedníků."],[2,"Řekl jim: „Jděte do vesnice před vámi. Hned po vstupu najdete přivázané oslátko, na kterém ještě nikdo neseděl. Odvažte je a přiveďte."],[3,"Kdyby se vás někdo zeptal, proč to děláte, řekněte: Pán je potřebuje a brzy je sem zase vrátí.“"],[4,"Učedníci odešli a našli oslátko přivázané venku u dveří domu, poblíž cesty. Začali je odvazovat."],[5,"Někteří z těch, kdo tam stáli, se jich zeptali: „Co to děláte? Proč odvazujete to oslátko?“"],[6,"Odpověděli jim přesně tak, jak jim řekl Ježíš, a lidé je nechali odejít."],[7,"Přivedli oslátko k Ježíšovi, položili na ně své pláště a Ježíš se na ně posadil."],[8,"Mnoho lidí rozprostíralo své pláště na cestu, jiní tam kladli zelené větve, které nasekali na polích."],[9,"Lidé před ním i za ním volali: „Hosana! Požehnaný, který přichází ve jménu Páně!"],[10,"Požehnané království našeho otce Davida, které přichází! Hosana na výsostech!“"],[11,"Ježíš vstoupil do Jeruzaléma a přišel do chrámu. Všechno si tam prohlédl, ale protože už bylo pozdě, odešel s Dvanácti do Betanie."]]},{"title":"Fíkovník a vyčištění chrámu","range":"Mk 11,12–19","thoughts":[],"verses":[[12,"Druhý den, když odcházeli z Betanie, dostal Ježíš hlad."],[13,"Z dálky uviděl fíkovník plný listí a šel se podívat, zda na něm něco najde. Když k němu přišel, našel jen listí, protože ještě nebyla doba fíků."],[14,"Řekl stromu: „Ať už z tebe nikdy nikdo nejí ovoce.“ Jeho učedníci to slyšeli."],[15,"Potom přišli do Jeruzaléma. Ježíš vstoupil do chrámu a začal vyhánět ty, kdo tam prodávali a nakupovali. Převracel stoly směnárníků i lavice prodavačů holubů."],[16,"Nedovolil ani, aby někdo přes chrámové nádvoří přenášel zboží."],[17,"Učil je: „Není snad napsáno: Můj dům bude nazýván domem modlitby pro všechny národy? Vy jste z něj ale udělali doupě lupičů.“"],[18,"Když se o tom doslechli přední kněží a učitelé Zákona, hledali způsob, jak Ježíše zabít. Báli se ho totiž, protože celý zástup žasl nad jeho učením."],[19,"Když nastal večer, Ježíš se svými učedníky odešel z města."]]},{"title":"Poučení od uschlého fíkovníku","range":"Mk 11,20–26","thoughts":[],"verses":[[20,"Když šli ráno kolem, uviděli, že fíkovník uschl až od kořenů."],[21,"Petr si vzpomněl a řekl Ježíšovi: „Mistře, podívej! Fíkovník, který jsi proklel, uschl.“"],[22,"Ježíš jim odpověděl: „Mějte víru v Boha."],[23,"Amen, říkám vám: Kdo by této hoře řekl: Zvedni se a vrhni se do moře, a ve svém srdci by nepochyboval, ale věřil, že se stane to, co říká, tomu se to stane."],[24,"Proto vám říkám: O cokoli v modlitbě prosíte, věřte, že jste to přijali, a budete to mít."],[25,"A když se modlíte, odpouštějte, pokud něco proti někomu máte, aby i váš Otec v nebi odpustil vaše provinění."],[26,"Jestliže však vy neodpustíte, ani váš Otec v nebi vám neodpustí vaše provinění.“"]]},{"title":"Otázka Ježíšovy autority","range":"Mk 11,27–33","thoughts":[],"verses":[[27,"Znovu přišli do Jeruzaléma. Když Ježíš procházel chrámem, přistoupili k němu přední kněží, učitelé Zákona a starší."],[28,"Zeptali se ho: „Jakou pravomocí tohle děláš? Kdo ti dal právo takto jednat?“"],[29,"Ježíš jim odpověděl: „Také já se vás na něco zeptám. Odpovězte mi, a potom vám řeknu, jakou pravomocí to dělám."],[30,"Janův křest pocházel z nebe, nebo od lidí? Odpovězte mi.“"],[31,"Začali se mezi sebou radit: „Když řekneme: Z nebe, zeptá se: Proč jste mu tedy neuvěřili?"],[32,"Máme ale říct: Od lidí?“ Báli se zástupu, protože všichni považovali Jana za skutečného proroka."],[33,"Proto Ježíšovi odpověděli: „Nevíme.“ Ježíš jim řekl: „Ani já vám tedy neřeknu, jakou pravomocí to dělám.“"]]}];

MARK_SECTIONS["12"] = [{"title":"Podobenství o zlých vinařích","range":"Mk 12,1–12","thoughts":[],"verses":[[1,"Ježíš k nim začal mluvit v podobenstvích: „Jeden člověk vysadil vinici, ohradil ji, vyhloubil lis a postavil strážní věž. Potom ji pronajal vinařům a odcestoval."],[2,"Když přišel čas sklizně, poslal k vinařům služebníka, aby od nich převzal svůj podíl z úrody vinice."],[3,"Vinaři ho však chytili, zbili a poslali zpátky s prázdnou."],[4,"Majitel k nim poslal jiného služebníka. Toho udeřili do hlavy a potupili."],[5,"Poslal dalšího, ale toho zabili. Poslal ještě mnoho jiných; některé zbili a jiné zabili."],[6,"Zbýval mu už jen jediný, jeho milovaný syn. Nakonec k nim poslal i jeho a říkal si: ‚K mému synovi snad budou mít úctu.‘"],[7,"Vinaři si však mezi sebou řekli: ‚Tohle je dědic. Pojďme ho zabít a dědictví bude naše.‘"],[8,"Chytili ho, zabili a vyhodili z vinice."],[9,"Co tedy udělá majitel vinice? Přijde, ty vinaře zahubí a vinici dá jiným."],[10,"Nečetli jste snad v Písmu: ‚Kámen, který stavitelé odmítli, se stal kamenem úhelným."],[11,"Udělal to Pán a v našich očích je to podivuhodné‘?“"],[12,"Chtěli Ježíše zatknout, protože pochopili, že toto podobenství vyprávěl o nich. Báli se však zástupu, a tak ho nechali být a odešli."]]},{"title":"Daň císaři","range":"Mk 12,13–17","thoughts":[],"verses":[[13,"Potom k němu poslali některé farizeje a herodiány, aby ho chytili za slovo."],[14,"Přišli a řekli mu: „Mistře, víme, že mluvíš pravdu a neohlížíš se na to, co si o tobě lidé myslí. Neděláš mezi lidmi rozdíly, ale pravdivě učíš Boží cestě. Je dovoleno platit daň císaři, nebo ne? Máme ji platit, nebo nemáme?“"],[15,"Ježíš však poznal jejich pokrytectví a řekl: „Proč mě zkoušíte? Přineste mi denár, ať se na něj podívám.“"],[16,"Přinesli mu ho. Ježíš se zeptal: „Čí je tento obraz a nápis?“ Odpověděli: „Císařův.“"],[17,"Ježíš jim řekl: „Dávejte tedy císaři, co patří císaři, a Bohu, co patří Bohu.“ Jeho odpověď je velmi překvapila."]]},{"title":"Otázka vzkříšení","range":"Mk 12,18–27","thoughts":[],"verses":[[18,"Potom k němu přišli saduceové, kteří tvrdí, že není vzkříšení, a položili mu otázku:"],[19,"„Mistře, Mojžíš nám napsal, že když někomu zemře bratr a zanechá po sobě manželku, ale žádné dítě, má si jeho bratr vzít vdovu a zplodit potomka svému zemřelému bratrovi."],[20,"Bylo sedm bratrů. První se oženil, ale zemřel bez potomka."],[21,"Vdovu si vzal druhý bratr, ale také zemřel a nezanechal potomka. Stejně dopadl i třetí."],[22,"Postupně si ji vzalo všech sedm bratrů, ale žádný nezanechal potomka. Nakonec zemřela i ta žena."],[23,"Až při vzkříšení vstanou z mrtvých, čí bude manželkou? Vždyť ji za manželku mělo všech sedm.“"],[24,"Ježíš jim odpověděl: „Nemýlíte se právě proto, že neznáte Písmo ani Boží moc?"],[25,"Když lidé vstanou z mrtvých, nebudou se ženit ani vdávat, ale budou jako andělé v nebi."],[26,"A pokud jde o to, že mrtví vstávají: Nečetli jste v Mojžíšově knize v příběhu o hořícím keři, jak mu Bůh řekl: ‚Já jsem Bůh Abrahamův, Bůh Izákův a Bůh Jákobův‘?"],[27,"Bůh není Bohem mrtvých, ale živých. Velmi se mýlíte.“"]]},{"title":"Největší přikázání","range":"Mk 12,28–34","thoughts":[],"verses":[[28,"Jeden z učitelů Zákona slyšel jejich rozhovor a všiml si, že Ježíš dobře odpověděl. Přistoupil k němu a zeptal se: „Které přikázání je ze všech nejdůležitější?“"],[29,"Ježíš odpověděl: „Nejdůležitější je: ‚Slyš, Izraeli, Pán, náš Bůh, je jediný Pán."],[30,"Miluj Pána, svého Boha, celým svým srdcem, celou svou duší, celou svou myslí a celou svou silou.‘"],[31,"Druhé je: ‚Miluj svého bližního jako sám sebe.‘ Žádné jiné přikázání není větší než tato dvě.“"],[32,"Učitel Zákona mu řekl: „Dobře, Mistře. Řekl jsi pravdu: Bůh je jeden a kromě něj žádný jiný není."],[33,"Milovat ho celým srdcem, celým rozumem a celou silou a milovat bližního jako sebe samého je důležitější než všechny zápalné oběti a ostatní oběti.“"],[34,"Když Ježíš viděl, že odpověděl rozumně, řekl mu: „Nejsi daleko od Božího království.“ Potom už se ho nikdo neodvážil na nic ptát."]]},{"title":"Čí syn je Mesiáš","range":"Mk 12,35–37","thoughts":[],"verses":[[35,"Když Ježíš učil v chrámu, zeptal se: „Jak mohou učitelé Zákona říkat, že Mesiáš je Davidův syn?"],[36,"Vždyť sám David pod vedením Ducha svatého řekl: ‚Pán řekl mému Pánu: Seď po mé pravici, dokud ti nepoložím nepřátele pod nohy.‘"],[37,"Sám David ho tedy nazývá Pánem. Jak potom může být jeho synem?“ Velký zástup mu rád naslouchal."]]},{"title":"Varování před zákoníky","range":"Mk 12,38–40","thoughts":[],"verses":[[38,"Ve svém učení Ježíš říkal: „Dávejte si pozor na učitele Zákona. Rádi chodí v dlouhých oděvech a chtějí, aby je lidé na veřejnosti uctivě zdravili."],[39,"V synagogách chtějí sedět na nejčestnějších místech a na hostinách mít nejlepší místa."],[40,"Přitom připravují vdovy o jejich domy a naoko se dlouze modlí. Ty čeká o to přísnější soud.“"]]},{"title":"Dar chudé vdovy","range":"Mk 12,41–44","thoughts":[],"verses":[[41,"Ježíš se posadil naproti chrámové pokladnici a pozoroval, jak do ní lidé vhazují peníze. Mnoho bohatých dávalo velké částky."],[42,"Potom přišla chudá vdova a vhodila dvě drobné mince velmi malé hodnoty."],[43,"Ježíš zavolal své učedníky a řekl jim: „Amen, říkám vám: Tato chudá vdova dala víc než všichni ostatní, kteří přispěli do pokladnice."],[44,"Oni totiž dávali ze svého přebytku. Ona však ze své chudoby dala všechno, co měla, celé své živobytí.“"]]}];

MARK_SECTIONS["13"] = [{"title":"Proroctví o zničení chrámu","range":"Mk 13,1–4","thoughts":[],"verses":[[1,"Když Ježíš vycházel z chrámu, jeden z jeho učedníků mu řekl: „Mistře, podívej na ty obrovské kameny a nádherné stavby!“"],[2,"Ježíš mu odpověděl: „Vidíš tyto veliké stavby? Nezůstane tu kámen na kameni; všechno bude zbořeno.“"],[3,"Později seděl na Olivové hoře naproti chrámu. Petr, Jakub, Jan a Ondřej se ho v soukromí zeptali:"],[4,"„Řekni nám, kdy se to stane a podle jakého znamení poznáme, že se to všechno blíží k naplnění?“"]]},{"title":"Začátek těžkostí","range":"Mk 13,5–13","thoughts":[],"verses":[[5,"Ježíš jim začal říkat: „Dávejte si pozor, aby vás někdo nesvedl."],[6,"Mnozí přijdou v mém jménu a budou říkat: ‚Já jsem to.‘ A svedou mnoho lidí."],[7,"Až uslyšíte o válkách a zprávy o dalších válkách, nelekejte se. To se musí stát, ale ještě to nebude konec."],[8,"Povstane národ proti národu a království proti království. Na různých místech budou zemětřesení a hlad. To všechno bude teprve začátek porodních bolestí."],[9,"Vy sami si dávejte pozor. Budou vás vydávat soudům, v synagogách vás budou bít a kvůli mně budete stát před vládci a králi, abyste před nimi vydali svědectví."],[10,"Nejprve však musí být evangelium hlásáno všem národům."],[11,"Když vás povedou k soudu, nedělejte si předem starosti, co budete říkat. Řekněte to, co vám v té chvíli bude dáno, protože nebudete mluvit jen vy, ale Duch svatý."],[12,"Bratr vydá na smrt bratra a otec své dítě. Děti povstanou proti rodičům a budou je posílat na smrt."],[13,"Kvůli mému jménu vás budou všichni nenávidět. Kdo však vytrvá až do konce, bude zachráněn."]]},{"title":"Velké soužení","range":"Mk 13,14–23","thoughts":[],"verses":[[14,"Až uvidíte ‚ohavnost zpustošení‘ stát tam, kde stát nemá — kdo čte, ať pochopí — tehdy ať ti, kdo budou v Judsku, utečou do hor."],[15,"Kdo bude na střeše, ať nesestupuje do domu a nechodí dovnitř pro své věci."],[16,"Kdo bude na poli, ať se nevrací pro svůj plášť."],[17,"Běda v těch dnech těhotným ženám a matkám, které budou kojit."],[18,"Modlete se, aby se to nestalo v zimě."],[19,"Ty dny totiž přinesou takové soužení, jaké nebylo od počátku stvoření, které Bůh stvořil, až dodnes a už ani nebude."],[20,"Kdyby Pán ty dny nezkrátil, nezachránil by se žádný člověk. Kvůli vyvoleným, které si vybral, však ty dny zkrátil."],[21,"Kdyby vám tehdy někdo řekl: ‚Podívejte, Mesiáš je tady!‘ nebo ‚Je tam!‘, nevěřte tomu."],[22,"Objeví se totiž falešní mesiášové a falešní proroci. Budou předvádět znamení a zázraky, aby pokud možno svedli i vyvolené."],[23,"Buďte proto ostražití. Všechno jsem vám řekl předem."]]},{"title":"Příchod Syna člověka","range":"Mk 13,24–27","thoughts":[],"verses":[[24,"„V těch dnech, po onom soužení, se zatmí slunce a měsíc přestane vydávat své světlo."],[25,"Hvězdy budou padat z nebe a nebeské mocnosti se otřesou."],[26,"Tehdy lidé uvidí Syna člověka přicházet v oblacích s velikou mocí a slávou."],[27,"Pošle své anděly a shromáždí své vyvolené ze všech světových stran, od nejzazších končin země až po nejzazší končiny nebe."]]},{"title":"Poučení od fíkovníku","range":"Mk 13,28–31","thoughts":[],"verses":[[28,"Vezměte si poučení z fíkovníku: Když jeho větve změknou a začnou rašit listy, víte, že se blíží léto."],[29,"Stejně tak až uvidíte, že se tyto věci dějí, vězte, že je to blízko, přede dveřmi."],[30,"Amen, říkám vám: Toto pokolení nepomine, dokud se to všechno nestane."],[31,"Nebe a země pominou, ale má slova nepominou."]]},{"title":"Nikdo nezná den ani hodinu","range":"Mk 13,32–37","thoughts":[],"verses":[[32,"O tom dni ani hodině však neví nikdo — ani andělé v nebi, ani Syn, pouze Otec."],[33,"Dávejte si pozor a bděte, protože nevíte, kdy ten čas přijde."],[34,"Je to jako s člověkem, který odcestoval. Opustil svůj dům, svěřil svým služebníkům odpovědnost, každému určil jeho práci a vrátnému přikázal, aby bděl."],[35,"Proto bděte, protože nevíte, kdy se pán domu vrátí — zda večer, o půlnoci, při kokrhání kohouta, nebo ráno."],[36,"Ať vás při svém náhlém příchodu nenajde spící."],[37,"Co říkám vám, říkám všem: Bděte!“"]]}];

MARK_SECTIONS["14"] = [{"title":"Spiknutí proti Ježíšovi","range":"Mk 14,1–2","thoughts":[],"verses":[[1,"Za dva dny měly být Velikonoce a svátek nekvašených chlebů. Velekněží a učitelé Zákona hledali způsob, jak Ježíše lstí zatknout a zabít."],[2,"Říkali si však: „Ne během svátků, aby mezi lidmi nevypukly nepokoje.“"]]},{"title":"Pomazání v Betanii","range":"Mk 14,3–9","thoughts":[],"verses":[[3,"Když byl Ježíš v Betanii v domě Šimona Malomocného a seděl u stolu, přišla žena s alabastrovou nádobkou velmi drahého čistého nardového oleje. Nádobku rozbila a olej mu vylila na hlavu."],[4,"Někteří se nad tím mezi sebou rozhořčovali: „Proč se tím olejem tak plýtvá?"],[5,"Mohl se prodat za více než tři sta denárů a peníze se mohly rozdat chudým.“ A ostře jí to vyčítali."],[6,"Ježíš však řekl: „Nechte ji být. Proč ji trápíte? Udělala pro mě dobrý skutek."],[7,"Chudé budete mít mezi sebou vždycky a můžete jim pomáhat, kdykoli budete chtít. Mě však vždycky mít nebudete."],[8,"Udělala, co mohla. Předem pomazala mé tělo k pohřbu."],[9,"Amen, říkám vám: Kdekoli na světě bude hlásáno evangelium, bude se na její památku vyprávět i o tom, co udělala.“"]]},{"title":"Jidášova zrada","range":"Mk 14,10–11","thoughts":[],"verses":[[10,"Jidáš Iškariotský, jeden z Dvanácti, odešel k velekněžím, aby jim Ježíše vydal."],[11,"Když to uslyšeli, zaradovali se a slíbili mu peníze. Jidáš pak hledal vhodnou příležitost, jak jim Ježíše vydat."]]},{"title":"Příprava velikonoční večeře","range":"Mk 14,12–16","thoughts":[],"verses":[[12,"První den svátku nekvašených chlebů, kdy se obětoval velikonoční beránek, se učedníci Ježíše zeptali: „Kam máme jít připravit velikonoční večeři, abys ji mohl jíst?“"],[13,"Poslal dva učedníky a řekl jim: „Jděte do města. Potká vás člověk, který ponese džbán vody. Jděte za ním."],[14,"Tam, kam vejde, řekněte majiteli domu: ‚Mistr se ptá: Kde je místnost, ve které mohu se svými učedníky jíst velikonoční večeři?‘"],[15,"Ukáže vám velkou místnost v horním patře, vybavenou a připravenou. Tam nám všechno nachystejte.“"],[16,"Učedníci odešli do města a našli všechno tak, jak jim Ježíš řekl. Připravili tedy velikonoční večeři."]]},{"title":"Poslední večeře","range":"Mk 14,17–25","thoughts":[],"verses":[[17,"Když nastal večer, přišel Ježíš s Dvanácti."],[18,"Když seděli u stolu a jedli, Ježíš řekl: „Amen, říkám vám: Jeden z vás mě zradí, jeden z těch, kdo se mnou jí.“"],[19,"Učedníci zesmutněli a jeden po druhém se ho začali ptát: „Snad ne já?“"],[20,"Ježíš jim odpověděl: „Je to jeden z Dvanácti, ten, který se mnou namáčí chléb do mísy."],[21,"Syn člověka odchází tak, jak je o něm napsáno. Ale běda člověku, který Syna člověka zradí. Pro toho člověka by bylo lépe, kdyby se vůbec nenarodil.“"],[22,"Když jedli, Ježíš vzal chléb, pronesl požehnání, lámal ho a dával jim se slovy: „Vezměte. Toto je mé tělo.“"],[23,"Potom vzal kalich, vzdal díky, podal jim ho a všichni z něj pili."],[24,"Řekl jim: „Toto je má krev smlouvy, která se prolévá za mnohé."],[25,"Amen, říkám vám: Už nebudu pít z plodu vinné révy až do dne, kdy budu pít nové víno v Božím království.“"]]},{"title":"Petr zapření předpovězeno","range":"Mk 14,26–31","thoughts":[],"verses":[[26,"Potom zazpívali chvalozpěv a vyšli na Olivovou horu."],[27,"Ježíš jim řekl: „Všichni ode mě odpadnete, protože je napsáno: ‚Udeřím pastýře a ovce se rozprchnou.‘"],[28,"Až ale vstanu z mrtvých, půjdu před vámi do Galileje.“"],[29,"Petr mu řekl: „I kdyby odpadli všichni ostatní, já ne.“"],[30,"Ježíš mu odpověděl: „Amen, říkám ti: Ještě dnes v noci, dříve než kohout dvakrát zakokrhá, mě třikrát zapřeš.“"],[31,"Petr však tím důrazněji tvrdil: „I kdybych měl s tebou zemřít, nikdy tě nezapřu.“ Stejně mluvili i ostatní."]]},{"title":"Ježíš v Getsemanech","range":"Mk 14,32–42","thoughts":[],"verses":[[32,"Přišli na místo zvané Getsemany. Ježíš řekl učedníkům: „Sedněte si tady, než se pomodlím.“"],[33,"Vzal s sebou Petra, Jakuba a Jana. Začala na něj doléhat hrůza a hluboká úzkost."],[34,"Řekl jim: „Má duše je sevřená smutkem až k smrti. Zůstaňte tady a bděte.“"],[35,"Poodešel kousek dál, padl na zem a modlil se, aby ho, pokud je to možné, ta hodina minula."],[36,"Říkal: „Abba, Otče, pro tebe je možné všechno. Vezmi ode mě tento kalich. Ale ať se nestane to, co chci já, nýbrž to, co chceš ty.“"],[37,"Vrátil se a našel učedníky spát. Řekl Petrovi: „Šimone, spíš? Nedokázal jsi jedinou hodinu bdít?"],[38,"Bděte a modlete se, abyste nepodlehli pokušení. Duch je odhodlaný, ale tělo je slabé.“"],[39,"Znovu odešel a modlil se stejnými slovy."],[40,"Když se vrátil, znovu je našel spát, protože se jim zavíraly oči. Nevěděli, co mu odpovědět."],[41,"Když přišel potřetí, řekl jim: „Ještě spíte a odpočíváte? Dost. Ta hodina přišla. Syn člověka je vydáván do rukou hříšníků."],[42,"Vstaňte, pojďme. Ten, kdo mě zrazuje, už je blízko.“"]]},{"title":"Ježíšovo zatčení","range":"Mk 14,43–52","thoughts":[],"verses":[[43,"Ještě když Ježíš mluvil, přišel Jidáš, jeden z Dvanácti. Doprovázel ho ozbrojený zástup s meči a holemi, který poslali velekněží, učitelé Zákona a starší."],[44,"Zrádce jim předem domluvil znamení: „Koho políbím, ten to je. Zatkněte ho a odveďte pod stráží.“"],[45,"Jakmile přišel, přistoupil k Ježíšovi, řekl: „Mistře!“ a políbil ho."],[46,"Oni se na Ježíše vrhli a zatkli ho."],[47,"Jeden z těch, kdo stáli poblíž, vytasil meč, udeřil služebníka velekněze a usekl mu ucho."],[48,"Ježíš jim řekl: „Vyšli jste na mě s meči a holemi, jako bych byl nějaký zločinec."],[49,"Každý den jsem byl mezi vámi a učil v chrámu, a nezatkli jste mě. Ale tak se naplňuje Písmo.“"],[50,"Všichni učedníci ho opustili a utekli."],[51,"Šel za ním také jeden mladík, který měl přes nahé tělo přehozené jen lněné plátno. Chtěli ho chytit,"],[52,"ale on plátno nechal v jejich rukou a utekl nahý."]]},{"title":"Ježíš před radou","range":"Mk 14,53–65","thoughts":[],"verses":[[53,"Ježíše odvedli k veleknězi. Sešli se tam všichni velekněží, starší a učitelé Zákona."],[54,"Petr šel zpovzdálí za ním až na nádvoří veleknězova domu. Sedl si tam mezi strážce a ohříval se u ohně."],[55,"Velekněží a celá rada hledali svědectví proti Ježíšovi, aby ho mohli odsoudit k smrti, ale žádné nenašli."],[56,"Mnozí proti němu sice falešně svědčili, jejich výpovědi se však neshodovaly."],[57,"Někteří vystoupili a falešně proti němu svědčili:"],[58,"„Slyšeli jsme ho říkat: ‚Zbořím tento chrám postavený lidskýma rukama a za tři dny postavím jiný, který lidskýma rukama postaven nebude.‘“"],[59,"Ani v tomto se ale jejich výpovědi neshodovaly."],[60,"Velekněz se postavil doprostřed a zeptal se Ježíše: „Nic neodpovíš? Co to proti tobě tito lidé vypovídají?“"],[61,"Ježíš však mlčel a nic neodpověděl. Velekněz se ho znovu zeptal: „Jsi Mesiáš, Syn Požehnaného?“"],[62,"Ježíš odpověděl: „Jsem. A uvidíte Syna člověka sedět po pravici Moci a přicházet s nebeskými oblaky.“"],[63,"Velekněz si roztrhl šaty a řekl: „K čemu ještě potřebujeme svědky?"],[64,"Slyšeli jste to rouhání. Co si o tom myslíte?“ Všichni ho odsoudili jako hodného smrti."],[65,"Někteří na něj začali plivat, zakrývali mu tvář, bili ho pěstmi a říkali: „Prorokuj!“ Také strážci ho bili."]]},{"title":"Petr zapírá Ježíše","range":"Mk 14,66–72","thoughts":[],"verses":[[66,"Když byl Petr dole na nádvoří, přišla jedna ze služek velekněze."],[67,"Uviděla Petra, jak se ohřívá, pozorně se na něj podívala a řekla: „Ty jsi byl také s tím Ježíšem z Nazareta.“"],[68,"Petr to však zapřel: „Nevím ani nerozumím, o čem mluvíš.“ Pak vyšel ven do průchodu."],[69,"Služka ho tam znovu uviděla a začala říkat okolostojícím: „Tenhle je jeden z nich.“"],[70,"Petr to znovu zapřel. Za chvíli mu lidé stojící kolem řekli: „Určitě jsi jeden z nich. Vždyť jsi Galilejec.“"],[71,"Petr se začal zaklínat a přísahat: „Toho člověka, o kterém mluvíte, neznám!“"],[72,"Vtom kohout zakokrhal podruhé. Petr si vzpomněl na Ježíšova slova: „Dříve než kohout dvakrát zakokrhá, třikrát mě zapřeš.“ Když si to uvědomil, rozplakal se."]]}];

MARK_SECTIONS["15"] = [{"title":"Ježíš před Pilátem","range":"Mk 15,1–15","thoughts":[],"verses":[[1,"Hned časně ráno se velekněží poradili se staršími, učiteli Zákona a celou radou. Ježíše svázali, odvedli a předali Pilátovi."],[2,"Pilát se ho zeptal: „Ty jsi král Židů?“ Ježíš odpověděl: „Ty to říkáš.“"],[3,"Velekněží ho obviňovali z mnoha věcí."],[4,"Pilát se ho znovu zeptal: „Nic neodpovídáš? Podívej, z kolika věcí tě obviňují.“"],[5,"Ježíš už ale nic neodpověděl, takže se Pilát divil."],[6,"O svátcích Pilát obvykle propouštěl jednoho vězně, o kterého lidé požádali."],[7,"Ve vězení byl tehdy muž jménem Barabáš. Byl uvězněn spolu s povstalci, kteří během vzpoury spáchali vraždu."],[8,"Zástup přišel k Pilátovi a začal ho žádat, aby udělal to, co pro ně obvykle dělal."],[9,"Pilát se jich zeptal: „Chcete, abych vám propustil krále Židů?“"],[10,"Věděl totiž, že mu velekněží Ježíše vydali ze závisti."],[11,"Velekněží však podnítili zástup, aby raději žádal propuštění Barabáše."],[12,"Pilát se jich znovu zeptal: „Co tedy mám udělat s tím, kterému říkáte král Židů?“"],[13,"Oni vykřikli: „Ukřižuj ho!“"],[14,"Pilát se zeptal: „A co zlého udělal?“ Oni však křičeli ještě hlasitěji: „Ukřižuj ho!“"],[15,"Pilát chtěl vyhovět zástupu, a tak jim propustil Barabáše. Ježíše nechal zbičovat a vydal ho k ukřižování."]]},{"title":"Vojáci se Ježíšovi posmívají","range":"Mk 15,16–20","thoughts":[],"verses":[[16,"Vojáci odvedli Ježíše dovnitř paláce, tedy do místodržitelského sídla, a svolali celou jednotku."],[17,"Oblékli ho do purpurového pláště a na hlavu mu nasadili korunu spletenou z trní."],[18,"Pak ho začali zdravit: „Buď zdráv, králi Židů!“"],[19,"Bili ho holí do hlavy, plivali na něj, klekali před ním a předstírali, že se mu klanějí."],[20,"Když se mu dost naposmívali, svlékli mu purpurový plášť a oblékli ho zpátky do jeho šatů. Potom ho odvedli, aby ho ukřižovali."]]},{"title":"Ukřižování","range":"Mk 15,21–32","thoughts":[],"verses":[[21,"Cestou přinutili nějakého Šimona z Kyrény, který se vracel z venkova, aby nesl Ježíšův kříž. Byl to otec Alexandra a Rufa."],[22,"Přivedli Ježíše na místo zvané Golgota, což znamená Místo lebky."],[23,"Nabízeli mu víno smíchané s myrhou, ale on je nepřijal."],[24,"Potom ho ukřižovali a rozdělili si jeho šaty. Losovali o ně, aby určili, kdo si co vezme."],[25,"Bylo devět hodin ráno, když ho ukřižovali."],[26,"Nápis s jeho proviněním zněl: „Král Židů.“"],[27,"Spolu s ním ukřižovali dva zločince, jednoho po jeho pravici a druhého po levici."],[28,"Tak se naplnilo Písmo: „Byl počítán mezi zločince.“"],[29,"Lidé, kteří procházeli kolem, se mu posmívali, potřásali hlavami a říkali: „Tak ty chceš zbořit chrám a za tři dny ho postavit?"],[30,"Zachraň sám sebe a sestup z kříže!“"],[31,"Podobně se mu mezi sebou posmívali i velekněží a učitelé Zákona: „Jiné zachraňoval, ale sám sebe zachránit nedokáže."],[32,"Ať teď Mesiáš, král Izraele, sestoupí z kříže. Až to uvidíme, uvěříme.“ Uráželi ho i ti, kteří byli ukřižováni spolu s ním."]]},{"title":"Ježíšova smrt","range":"Mk 15,33–41","thoughts":[],"verses":[[33,"V poledne padla na celou zemi tma a trvala až do tří hodin odpoledne."],[34,"Kolem třetí hodiny Ježíš hlasitě zvolal: „Eloi, Eloi, lema sabachtani?“ To znamená: „Bože můj, Bože můj, proč jsi mě opustil?“"],[35,"Někteří z těch, kdo stáli poblíž, to zaslechli a říkali: „Podívejte, volá Eliáše.“"],[36,"Jeden z nich běžel, namočil houbu do kyselého vína, nasadil ji na tyč a dával mu pít. Říkal přitom: „Počkejte, uvidíme, jestli přijde Eliáš a sundá ho dolů.“"],[37,"Ježíš hlasitě vykřikl a zemřel."],[38,"Chrámová opona se roztrhla vedví odshora až dolů."],[39,"Když setník, který stál naproti Ježíšovi, viděl, jak zemřel, řekl: „Ten člověk byl opravdu Boží Syn.“"],[40,"Zpovzdálí se dívaly také ženy. Byla mezi nimi Marie Magdaléna, Marie, matka Jakuba mladšího a Josese, a Salome."],[41,"Tyto ženy Ježíše následovaly a staraly se o něj už v Galileji. Bylo tam také mnoho dalších žen, které s ním přišly do Jeruzaléma."]]},{"title":"Ježíšův pohřeb","range":"Mk 15,42–47","thoughts":[],"verses":[[42,"Už se připozdívalo. Byl den přípravy, tedy den před sobotou."],[43,"Josef z Arimatie, vážený člen rady, který také očekával Boží království, se odvážil jít k Pilátovi a požádal ho o Ježíšovo tělo."],[44,"Pilát se podivil, že už Ježíš zemřel. Zavolal si setníka a zeptal se ho, zda je už opravdu mrtvý."],[45,"Když mu to setník potvrdil, dovolil Josefovi tělo převzít."],[46,"Josef koupil lněné plátno, Ježíše sňal z kříže, zabalil ho do plátna a uložil do hrobu vytesaného ve skále. Ke vchodu do hrobu pak přivalil kámen."],[47,"Marie Magdaléna a Marie, matka Josese, se dívaly, kam Ježíše položili."]]}];

MARK_SECTIONS["16"] = [{"title":"Prázdný hrob","range":"Mk 16,1–8","thoughts":[],"verses":[[1,"když pominula sobota, Maria Magdaléna a Maria Jakubova a Salome nakoupily vonných věcí, aby přijdouce, pomazaly Ježíše."],[2,"Protož velmi ráno v první den po sobotě přišly k hrobu, an již slunce vzešlo."],[3,"pravily vespolek: Kdo nám odvalí kámen ode dveří hrobových?"],[4,"(A vzhlédše, uzřely odvalený kámen.) Byl zajisté veliký velmi."],[5,"všelše do hrobu, uzřely mládence, an sedí na pravici, oděného rouchem bílým. A ulekly se."],[6,"On pak řekl jim: Nebojte se. Ježíše hledáte Nazaretského, toho ukřižovaného. Vstalť je, neníť ho tuto; aj, místo, kdež ho byli položili."],[7,"Ale jděte, povězte učedníkům jeho i Petrovi, žeť vás předejde do Galilee. Tam ho uzříte, jakž pověděl vám."],[8,"vyšelše rychle, utekly od hrobu; nebo přišel na ně strach a hrůza. A aniž komu co řekly, nebo se bály."]]},{"title":"Ježíš se ukazuje učedníkům","range":"Mk 16,9–14","thoughts":[],"verses":[[9,"Vstav pak Ježíš z mrtvých ráno v neděli, ukázal se nejprv Marii Magdaléně, z níž byl vyvrhl sedm ďáblů."],[10,"Ona pak šedši, zvěstovala těm, kteříž s ním bývali, lkajícím a plačícím."],[11,"oni když uslyšelše, že by živ byl, a vidín od ní, nevěřili."],[12,"pak dvěma z nich jdoucím ukázal se v jiné způsobě, když šli přes pole."],[13,"ti šedše, pověděli jiným. Ani těm nevěřili."],[14,"sedícím spolu jedenácti ukázal se, a trestal nedověru jejich a tvrdost srdce, že těm, kteříž ho viděli vzkříšeného, nevěřili."]]},{"title":"Poslání učedníků","range":"Mk 16,15–20","thoughts":[],"verses":[[15,"řekl jim: Jdouce po všem světě, kažte evangelium všemu stvoření."],[16,"Kdož uvěří a pokřtí se, spasen bude; kdož pak neuvěří, budeť zatracen."],[17,"Znamení pak ti, kteříž uvěří, tato míti budou: Ve jménu mém ďábly budou vymítati, jazyky novými mluviti,"],[18,"Hady bráti, a jestliže by co jedovatého pili, nikoliť jim neuškodí; na nemocné ruce vzkládati budou, a dobře se míti budou."],[19,"Když pak jim odmluvil Pán, zhůru vzat je do nebe, a sedí na pravici Boží."],[20,"oni vyšelše, kázali všudy, a Pán jim pomáhal, a slov jejich potvrzoval činěním divů."]]}];

